package dev.aragonite.powersync.client;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import org.json.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;private EditText server,code;private CheckBox notes,reader;private TransitionController controller;private static volatile boolean busy;private static java.lang.ref.WeakReference<MainActivity> active=new java.lang.ref.WeakReference<>(null);private LinearLayout layout;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);active=new java.lang.ref.WeakReference<>(this);controller=new TransitionController(this);ScrollView scroll=new ScrollView(this);layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);int pad=(int)(20*getResources().getDisplayMetrics().density);layout.setPadding(pad,pad,pad,pad);scroll.addView(layout);setContentView(scroll);TextView title=new TextView(this);title.setText(R.string.app_name);title.setTextSize(30);layout.addView(title);TextView intro=new TextView(this);intro.setText(R.string.intro);layout.addView(intro);status=new TextView(this);status.setTextSize(17);status.setPadding(0,pad,0,pad);layout.addView(status);server=new EditText(this);server.setHint(R.string.hint_server);server.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);layout.addView(server);code=new EditText(this);code.setHint(R.string.hint_code);code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);layout.addView(code);notes=new CheckBox(this);notes.setText(R.string.check_notes);layout.addView(notes);reader=new CheckBox(this);reader.setText(R.string.check_reader);layout.addView(reader);TextView scope=new TextView(this);scope.setText(R.string.scope);layout.addView(scope);
 button(R.string.button_grant_access,()->startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName()))));button(R.string.button_enroll,()->{String url=server.getText().toString(),secret=code.getText().toString();run(()->{JSONObject preview=controller.enroll(SafeURL.base(url),secret);runOnUiThread(()->code.setText(""));return getString(R.string.result_enrolled,preview.getString("serverURL"));});});button(R.string.button_connect,()->new AlertDialog.Builder(this).setTitle(R.string.dialog_connect_title).setMessage(R.string.dialog_connect_message).setPositiveButton(R.string.action_connect,(d,w)->{boolean n=notes.isChecked(),r=reader.isChecked();run(()->{controller.connect(n,r);return getString(R.string.result_connected);});}).setNegativeButton(R.string.action_cancel,null).show());button(R.string.button_update_endpoints,this::showEndpointUpdate);button(R.string.button_return,()->new AlertDialog.Builder(this).setTitle(R.string.dialog_return_title).setMessage(R.string.dialog_return_message).setPositiveButton(R.string.action_restore,(d,w)->run(()->{controller.restore();return describe(controller.status());})).setNegativeButton(R.string.action_cancel,null).show());button(R.string.button_refresh_status,()->run(()->describe(controller.status())));button(R.string.button_recovery_status,()->run(()->controller.recoveryStatus().optString("summary",getString(R.string.recovery_status_default))));button(R.string.button_recover_audio,this::showAudioRecovery);button(R.string.button_open_settings,()->{Intent i=getPackageManager().getLaunchIntentForPackage("com.onyx");if(i!=null)startActivity(i);else startActivity(new Intent(Settings.ACTION_SETTINGS));});if(busy)status.setText(R.string.status_working);else run(()->describe(controller.status()));}

 private void showEndpointUpdate(){run(()->{
  JSONObject plan=controller.endpointPlan();JSONArray changes=plan.getJSONArray("changes");if(changes.length()==0)return getString(R.string.endpoints_current);
  StringBuilder list=new StringBuilder();for(int i=0;i<changes.length();i++)list.append("\n• ").append(changes.getString(i));
  runOnUiThread(()->{if(isDestroyed())return;new AlertDialog.Builder(this).setTitle(R.string.dialog_endpoints_title).setMessage(getString(R.string.dialog_endpoints_message)+list).setPositiveButton(R.string.action_update,(d,w)->run(controller::applyEndpointUpdate)).setNegativeButton(R.string.action_cancel,null).show();});
  return getResources().getQuantityString(R.plurals.endpoints_differ,changes.length(),changes.length());
 });}
 private void showAudioRecovery(){run(()->{
  JSONArray items=controller.audioRecoveries();if(items.length()==0)return getString(R.string.audio_none);
  String[] labels=new String[items.length()];for(int i=0;i<labels.length;i++){JSONObject v=items.getJSONObject(i);labels[i]=getString(R.string.audio_label,v.getString("title"),v.getString("fileName"));}
  runOnUiThread(()->{if(isDestroyed())return;new AlertDialog.Builder(this).setTitle(R.string.dialog_audio_choose_title).setItems(labels,(d,n)->{try{reviewAudio(items.getJSONObject(n).getString("operationId"));}catch(JSONException e){status.setText(R.string.audio_invalid_list);}}).setNegativeButton(R.string.action_cancel,null).show();});
  return getString(R.string.audio_choose);
 });}
 private void reviewAudio(String operation){run(()->{
  AudioCacheRepair repair=controller.audioPacket(operation);String result=controller.inspectAudio(repair);
  if("healthy".equals(result))return getString(R.string.audio_healthy);
  if("missing".equals(result))return getString(R.string.audio_missing);
  if(!"repairable".equals(result))return getString(R.string.audio_mismatch);
  runOnUiThread(()->{if(isDestroyed())return;new AlertDialog.Builder(this).setTitle(R.string.dialog_audio_recover_title).setMessage(R.string.dialog_audio_recover_message).setPositiveButton(R.string.action_recover,(d,w)->run(()->{controller.repairAudio(repair);return getString(R.string.audio_recovered);})).setNegativeButton(R.string.action_cancel,null).show();});
  return getString(R.string.audio_repairable);
 });}
 private interface Work {String call()throws Exception;}
 private void button(int label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->{if(!busy)action.run();});layout.addView(b);}
 private void run(Work work){if(busy)return;busy=true;status.setText(R.string.status_working);worker.execute(()->{String result;try{result=work.call();}catch(Exception e){result=getString(R.string.stopped_safely,safe(e));}String text=result;runOnUiThread(()->{busy=false;MainActivity visible=active.get();if(visible!=null&&!visible.isDestroyed())visible.status.setText(text);});});}
 private String safe(Exception e){Throwable t=e;while(t.getCause()!=null)t=t.getCause();if(t instanceof UserError)return ((UserError)t).text(this);if(t instanceof java.io.IOException)return getString(R.string.error_unavailable);return getString(R.string.error_unexpected,t.getClass().getSimpleName());}
 private String describe(JSONObject s)throws Exception {JSONObject f=s.getJSONObject("flags");return getString(R.string.status_description,s.getString("clusterId"),getString(s.getBoolean("accountLoggedIn")?R.string.account_signed_in:R.string.account_signed_out),onOff(f.getString("notes")),onOff(f.getString("reader")),phase(s.getString("phase")),getString(s.getBoolean("hasBaseline")?R.string.yes:R.string.no));}
 private String onOff(String flag){return getString("true".equals(flag)?R.string.state_on:"false".equals(flag)?R.string.state_off:R.string.state_unknown);}
 // Settled phases get words; the transient ones are shown as their code, which only matters mid-transition.
 private String phase(String p){switch(p){case "active":return getString(R.string.phase_active);case "restored":return getString(R.string.phase_restored);case "not_configured":return getString(R.string.phase_not_configured);case "needs_signin":return getString(R.string.phase_needs_signin);case "failed":return getString(R.string.phase_failed);default:return p;}}
 @Override protected void onDestroy(){if(active.get()==this)active.clear();super.onDestroy();}
}
